//! Independent polynomial camera observations, never generated by the fitted camera model.
use ftx_core::{Mat3, Vec2, Vec3};
use ftx_measure::{
    photo::intrinsics::{CalibrationInput, Control, Corner, DistortionFit, View, calibrate_camera},
    triangulate::{FrameId, Partition},
};
use serde_json::json;

fn fixture() -> CalibrationInput {
    let controls: Vec<_> = (0..48)
        .map(|i| Control {
            id: format!("p{i:02}"),
            sheet_xz_m: Vec2::new((i % 8) as f64 * 0.06 - 0.21, (i / 8) as f64 * 0.06 - 0.15),
        })
        .collect();
    let base = Mat3::from_rows([[1., 0., 0.], [0., 0., -1.], [0., 1., 0.]]);
    let views = [
        (0.35, 0.12, -0.18, -0.10, 0.80),
        (-0.45, 0.3, 0.16, 0.13, 0.75),
        (0.2, -0.55, -0.12, 0.18, 0.85),
        (-0.3, -0.25, 0.23, -0.14, 0.8),
        (0.5, -0.4, 0.03, -0.04, 0.66),
        (-0.2, 0.5, -0.24, 0.06, 0.9),
    ]
    .iter()
    .enumerate()
    .map(|(i, &(a, b, tx, ty, tz))| {
        let r = Mat3::rotation(Vec3::new(1., 0., 0.), a)
            * Mat3::rotation(Vec3::new(0., 1., 0.), b)
            * base;
        let t = Vec3::new(tx, ty, tz);
        View {
            frame: FrameId {
                stream: "synthetic-brown".into(),
                timestamp_us: i as u64 * 100000,
            },
            partition: if i == 5 {
                Partition::HeldOut
            } else {
                Partition::Fit
            },
            corners: controls
                .iter()
                .enumerate()
                .map(|(i, p)| {
                    let q = r.mul_vec(Vec3::new(p.sheet_xz_m.x, 0., p.sheet_xz_m.y)) + t;
                    let (x, y) = (q.x / q.z, q.y / q.z);
                    let r2 = x * x + y * y;
                    let radial = 1.0 + 0.12 * r2 - 0.035 * r2 * r2 + 0.009 * r2 * r2 * r2;
                    let xd = x * radial + 2.0 * 0.002 * x * y - 0.0015 * (r2 + 2.0 * x * x);
                    let yd = y * radial + 0.002 * (r2 + 2.0 * y * y) - 2.0 * 0.0015 * x * y;
                    Corner {
                        id: p.id.clone(),
                        pixel_px: Vec2::new(1050. * xd + 790., 1000. * yd + 610.),
                        partition: if [0, 7, 40, 47].contains(&i) {
                            Partition::HeldOut
                        } else {
                            Partition::Fit
                        },
                    }
                })
                .collect(),
        }
    })
    .collect();
    CalibrationInput {
        schema: "ftx-camera-calibration-input/1".into(),
        image_model: "brown5_zero_skew".into(),
        lens_id: "synthetic-brown".into(),
        pinhole_evidence: String::new(),
        distortion_fit: Some(DistortionFit {
            model_evidence: "Independent synthetic Brown lens; not a camera calibration".into(),
            max_radius: 0.9,
            max_iterations: 80,
        }),
        reference_evidence: "Synthetic 60 mm planar grid".into(),
        image_size_px: [1600, 1200],
        rotation_cw_deg: 0,
        controls,
        views,
    }
}

#[test]
fn jointly_recovers_focals_principal_point_and_all_five_distortion_coefficients() {
    let input = fixture();
    let report = calibrate_camera(&input).unwrap();
    assert_eq!(report.status, "ACCEPTED", "{report:#?}");
    let k = report.solution.as_ref().unwrap().intrinsics;
    assert!(
        (k.focal_px - Vec2::new(1050., 1000.)).norm() < 1e-5,
        "{k:?}"
    );
    assert!(
        (k.principal_px - Vec2::new(790., 610.)).norm() < 1e-5,
        "{k:?}"
    );
    for (a, b) in k.distortion.radial.iter().zip([0.12, -0.035, 0.009]) {
        assert!((a - b).abs() < 1e-6, "{k:?}");
    }
    for (a, b) in k.distortion.tangential.iter().zip([0.002, -0.0015]) {
        assert!((a - b).abs() < 1e-7, "{k:?}");
    }
    assert_eq!(k.distortion.max_radius, 0.9);
    k.validate().unwrap();
    assert!(
        report
            .checks
            .iter()
            .flat_map(|v| &v.corners)
            .all(|c| c.error_px.unwrap() < 1e-6)
    );
    let diagnostics = report.refinement.as_ref().unwrap();
    assert!(
        diagnostics
            .objective_history
            .windows(2)
            .all(|w| w[1] < w[0])
    );
    assert_eq!(diagnostics.termination, "gradient_converged");
    assert!(diagnostics.fit_radius_range.unwrap()[1] < 0.9);
    // This scene genuinely needs more than a raw-pixel pinhole fit.
    let mut pinhole = input;
    pinhole.image_model = "pinhole_zero_skew".into();
    pinhole.pinhole_evidence =
        "Deliberately incorrect pinhole assumption in a negative test".into();
    pinhole.distortion_fit = None;
    assert!(calibrate_camera(&pinhole).unwrap().solution.is_none());
}

#[test]
fn held_out_pixels_cannot_steer_the_lens_or_joint_convergence() {
    let input = fixture();
    let good = calibrate_camera(&input).unwrap();
    assert!(good.solution.is_some());
    for held_view in [false, true] {
        let mut bad = input.clone();
        let i = if held_view { 5 } else { 0 };
        bad.views[i].corners[0].pixel_px.x += 25.;
        let report = calibrate_camera(&bad).unwrap();
        assert_eq!(report.status, "REJECTED", "{report:#?}");
        assert!(report.solution.is_none());
        assert_eq!(json!(good.refinement), json!(report.refinement));
        for (a, b) in good.checks[1..5].iter().zip(&report.checks[1..5]) {
            assert_eq!(json!(a), json!(b));
        }
    }
    // Fit points from a held-out view may change only that view's pose fit, never the lens.
    let mut changed = input;
    changed.views[5].corners[3].pixel_px.x += 25.;
    let bad = calibrate_camera(&changed).unwrap();
    assert!(bad.solution.is_none());
    assert_eq!(json!(good.refinement), json!(bad.refinement));
}

#[test]
fn ordering_and_metric_reference_similarity_do_not_change_the_lens() {
    let input = fixture();
    let good = calibrate_camera(&input).unwrap();
    let mut reordered = input.clone();
    reordered.views.reverse();
    reordered.controls.reverse();
    for v in &mut reordered.views {
        v.corners.reverse();
    }
    assert_eq!(json!(good), json!(calibrate_camera(&reordered).unwrap()));
    let mut scaled = input;
    for p in &mut scaled.controls {
        p.sheet_xz_m = p.sheet_xz_m * 0.1 + Vec2::new(2., -3.);
    }
    let other = calibrate_camera(&scaled).unwrap();
    assert!(other.solution.is_some(), "{other:#?}");
    let a = good.solution.unwrap().intrinsics;
    let b = other.solution.unwrap().intrinsics;
    assert!((a.focal_px - b.focal_px).norm() < 1e-5);
    assert!((a.principal_px - b.principal_px).norm() < 1e-5);
}

#[test]
fn sparse_views_budget_stop_and_invalid_models_never_publish_calibration() {
    let input = fixture();
    let mut short = input.clone();
    short.views.truncate(4);
    assert!(calibrate_camera(&short).unwrap().solution.is_none());
    let mut short = input.clone();
    short.distortion_fit.as_mut().unwrap().max_iterations = 1;
    let report = calibrate_camera(&short).unwrap();
    assert!(report.solution.is_none());
    assert!(
        report.flags.iter().any(|s| s.contains("BUDGET_STOP")),
        "{report:#?}"
    );
    for (model, radius) in [("pinhole_zero_skew", 0.9), ("brown5_zero_skew", -1.)] {
        let mut bad = input.clone();
        bad.image_model = model.into();
        bad.distortion_fit.as_mut().unwrap().max_radius = radius;
        assert!(calibrate_camera(&bad).is_err());
    }
    let mut narrow = input;
    narrow.distortion_fit.as_mut().unwrap().max_radius = 0.01;
    assert!(calibrate_camera(&narrow).unwrap().solution.is_none());
}

#[test]
fn noisy_corners_report_their_residuals_instead_of_being_trimmed() {
    let mut input = fixture();
    for (i, v) in input.views.iter_mut().enumerate() {
        for (j, p) in v.corners.iter_mut().enumerate() {
            p.pixel_px.x += 0.05 * ((i * 17 + j * 13) % 11) as f64 - 0.25;
            p.pixel_px.y += 0.04 * ((i * 23 + j * 7) % 13) as f64 - 0.24;
        }
    }
    let report = calibrate_camera(&input).unwrap();
    assert_eq!(report.status, "ACCEPTED", "{report:#?}");
    assert_eq!(
        report.checks.iter().map(|v| v.corners.len()).sum::<usize>(),
        288
    );
    let d = report.refinement.as_ref().unwrap();
    assert!(d.objective_history.last().unwrap() > &0.01);
    assert!(d.objective_history.windows(2).all(|w| w[1] < w[0]));
    assert!(
        (report.solution.as_ref().unwrap().intrinsics.focal_px - Vec2::new(1050., 1000.)).norm()
            < 10.
    );
}
